values ('bacc2010-2014-4200-8000-000000000003', 'kh-grade12-social-mathematics-function-study', null, 2014, 'open', 'គេមានអនុគមន៍ $f(x)=\dfrac{(x+2)(x-2)}{(1-x)}$។
